def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []
        intervals = sorted(intervals)
        merged = [intervals[0]]
        for start, end in intervals[1:]:
            if start <= merged[-1][1]:
                merged[-1][1] = max(merged[-1][1], end)
            else:
                merged.append([start, end])
        return merged

    # Filter out empty intervals and merge overlapping intervals
    a_valid = [interval for interval in a if interval[0] < interval[1]]
    b_valid = [interval for interval in b if interval[0] < interval[1]]

    a_merged = merge_intervals(a_valid)
    b_merged = merge_intervals(b_valid)

    if not a_merged:
        return []

    result = []

    for a_start, a_end in a_merged:
        current_ranges = [[a_start, a_end]]

        for b_start, b_end in b_merged:
            new_ranges = []
            for curr_start, curr_end in current_ranges:
                # No overlap
                if b_end <= curr_start or b_start >= curr_end:
                    new_ranges.append([curr_start, curr_end])
                else:
                    # There is overlap, keep the non-overlapping parts
                    if curr_start < b_start:
                        new_ranges.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_ranges.append([b_end, curr_end])
            current_ranges = new_ranges

        result.extend(current_ranges)

    return result

